import { useState, useEffect } from 'react';
import { useNavigate, Link, Routes, Route } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';
import '@fortawesome/fontawesome-free/css/all.min.css';

import Home from './Home';
import Students from './Students';
import Courses from './Courses';
import Questions from './Questions';

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(true);

  useEffect(() => {
    const path = window.location.pathname;
    if (path === '/admin') setActiveTab('dashboard');
    else if (path === '/admin/students') setActiveTab('students');
    else if (path === '/admin/courses') setActiveTab('courses');
    else if (path === '/admin/questions') setActiveTab('questions');
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: 'fa-chart-line', path: '/admin' },
    { id: 'students', label: 'Students', icon: 'fa-users', path: '/admin/students' },
    { id: 'courses', label: 'Courses', icon: 'fa-book-open', path: '/admin/courses' },
    { id: 'questions', label: 'Questions', icon: 'fa-question-circle', path: '/admin/questions' }
  ];

  return (
    <div style={{ display: 'flex', minHeight: '100vh', background: '#f1f5f9' }}>

      {/* SIDEBAR */}
      <div style={{
        width: '250px',
        background: '#0f172a',
        color: 'white',
        position: 'fixed',
        height: '100vh'
      }}>
        <div style={{ padding: '20px', textAlign: 'center' }}>
          <img src="/logo.png" style={{ width: '70px', borderRadius: '50%' }} />
          <h6 style={{ marginTop: '10px' }}>Admin Panel</h6>
        </div>

        {menuItems.map(item => (
          <Link
            key={item.id}
            to={item.path}
            onClick={() => setActiveTab(item.id)}
            style={{
              display: 'flex',
              padding: '14px 20px',
              color: activeTab === item.id ? '#fff' : '#94a3b8',
              background: activeTab === item.id ? '#1e293b' : 'transparent',
              borderLeft: activeTab === item.id ? '4px solid #3b82f6' : 'none',
              textDecoration: 'none'
            }}
          >
            <i className={`fas ${item.icon}`} style={{ marginRight: '10px' }}></i>
            {item.label}
          </Link>
        ))}
      </div>

      {/* MAIN */}
      <div style={{ marginLeft: '250px', width: '100%', padding: '25px' }}>

        {/* HEADER */}
        <div style={{
          background: '#fff',
          padding: '20px',
          borderRadius: '12px',
          marginBottom: '25px',
          display: 'flex',
          justifyContent: 'space-between'
        }}>
          <div>
            <h4 style={{ margin: 0 }}>Admin Dashboard</h4>
            <small style={{ color: '#64748b' }}>
              Overview of platform performance
            </small>
          </div>

          <button
            onClick={handleLogout}
            style={{
              background: '#ef4444',
              border: 'none',
              color: '#fff',
              padding: '8px 15px',
              borderRadius: '8px'
            }}
          >
            Logout
          </button>
        </div>

        {/* DASHBOARD CONTENT ONLY FOR HOME */}
        {activeTab === 'dashboard' && (
          <>
            {/* STATS */}
            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(4, 1fr)',
              gap: '20px',
              marginBottom: '25px'
            }}>
              {[
                { title: 'Students', value: 10, color: '#3b82f6', icon: 'fa-users' },
                { title: 'Courses', value: 4, color: '#22c55e', icon: 'fa-book' },
                { title: 'Questions', value: 55, color: '#06b6d4', icon: 'fa-question' },
                { title: 'Active', value: 7, color: '#f59e0b', icon: 'fa-signal' }
              ].map((card, i) => (
                <div key={i} style={{
                  background: '#fff',
                  padding: '20px',
                  borderRadius: '12px',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  boxShadow: '0 5px 20px rgba(0,0,0,0.05)'
                }}>
                  <div>
                    <small style={{ color: '#64748b' }}>{card.title}</small>
                    <h4>{card.value}</h4>
                  </div>
                  <i className={`fas ${card.icon}`} style={{
                    fontSize: '22px',
                    color: card.color
                  }}></i>
                </div>
              ))}
            </div>

            {/* MAIN GRID */}
            <div style={{
              display: 'grid',
              gridTemplateColumns: '2fr 1fr',
              gap: '20px'
            }}>

              {/* ACTIVITY */}
              <div style={{
                background: '#fff',
                padding: '20px',
                borderRadius: '12px',
                boxShadow: '0 5px 20px rgba(0,0,0,0.05)'
              }}>
                <h5>Recent Activity</h5>
                <ul style={{ padding: 0, listStyle: 'none' }}>
                  <li>✔ New student registered</li>
                  <li>✔ Course added</li>
                  <li>✔ Quiz completed</li>
                  <li>✔ Question updated</li>
                </ul>
              </div>

              {/* QUICK ACTIONS */}
              <div style={{
                background: '#fff',
                padding: '20px',
                borderRadius: '12px',
                boxShadow: '0 5px 20px rgba(0,0,0,0.05)'
              }}>
                <h5>Quick Actions</h5>

                <button className="btn btn-primary w-100 mb-2">
                  Add Course
                </button>

                <button className="btn btn-success w-100 mb-2">
                  Add Question
                </button>

                <button className="btn btn-dark w-100">
                  Manage Students
                </button>
              </div>
            </div>
          </>
        )}

        {/* ROUTES */}
        {activeTab !== 'dashboard' && (
          <div style={{
            background: '#fff',
            padding: '20px',
            borderRadius: '12px'
          }}>
            <Routes>
              <Route index element={<Home />} />
              <Route path="students" element={<Students />} />
              <Route path="courses" element={<Courses />} />
              <Route path="questions" element={<Questions />} />
            </Routes>
          </div>
        )}

      </div>
    </div>
  );
}
